package com.example.agriculturalapp.data.local

import androidx.room.Dao
import androidx.room.Delete
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface ResponseDao {
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertResult(result: ResultEntity)

    @Query("SELECT * FROM results ORDER BY timestamp DESC")
    fun getAllResults(): Flow<List<ResultEntity>>

    @Delete
    suspend fun deleteResult(result: ResultEntity)

    @Query("SELECT * FROM results WHERE analysisType = :analysisType LIMIT 1")
    suspend fun getResultByAnalysisType(analysisType: String): ResultEntity?
}

package com.example.agriculturalapp.data.mapper
import com.example.agriculturalapp.data.dtomodel.GeminiResponse import com.example.agriculturalapp.domain.entity.AIResponse import javax.inject.Inject
class GeminiMapper @Inject constructor() { fun toDomain(prompt: String, response: GeminiResponse): AIResponse { val text = response.candidates .firstOrNull() ?.content ?.parts ?.firstOrNull() ?.text ?.trim() .orEmpty()
return AIResponse( prompt = prompt, response = text.ifBlank { "No response generated." }, timestamp = System.currentTimeMillis() ) } }

package com.example.agriculturalapp.data.mapper

import com.example.agriculturalapp.data.local.ResultEntity
import com.example.agriculturalapp.domain.entity.AIResponse
import javax.inject.Inject

class ResultEntityMapper @Inject constructor() {
    fun toEntity(response: AIResponse): ResultEntity {
        return ResultEntity(
            id = response.id,
            analysisType = response.prompt,
            aiResponse = response.response,
            timestamp = response.timestamp
        )
    }

    fun toDomain(entity: ResultEntity): AIResponse {
        return AIResponse(
            id = entity.id,
            prompt = entity.analysisType,
            response = entity.aiResponse,
            timestamp = entity.timestamp
        )
    }
}

