    private val getSavedResponsesUseCase: GetSavedResponsesUseCase
) : ViewModel() {

    var results by mutableStateOf<List<AIResponse>>(emptyList())
        private set

    init {
        viewModelScope.launch {
            getSavedResponsesUseCase().collectLatest { saved ->
                results = saved
            }
        }
    }
}

